const start = new Date($json.PROJECT_START_DATE + 'T00:00:00+02:00');
const now = new Date();
const projectDay = Math.floor((now - start) / (24 * 60 * 60 * 1000)) + 1;

return [{
  json: {
    ...$json,
    PROJECT_DAY: projectDay
  }
}];

const story = $json.STORY_ENGINE || {
  category: $json.STORY_CATEGORY,
  topic: $json.STORY_TOPIC,
  hook: $json.STORY_HOOK,
  lesson: $json.STORY_LESSON,
};

const prompt = `
TELEGRAM POST GENERATOR

Brand: ${$json.BRAND_NAME}
Project day: Day ${$json.PROJECT_DAY}
Channel: ${$json.TELEGRAM_PUBLIC_CHANNEL}

Use this Story Engine output as the only content source:
${JSON.stringify(story, null, 2)}

Brand context:
${$json.BRAND_CONTEXT}

Rules:
- Generate one Telegram public post.
- English first, then Russian.
- Lead with the hook or lesson, not the internal event.
- Ground everything in the Story Engine topic.
- Do not use random business advice.
- Do not invent metrics, customers, revenue, trading results, or launches.
- Do not drift back to cooldown bugs, exit safety, or RSI filters unless the Story Engine selected Trading Bot Lessons.
- Practical ForgeView build-in-public tone.
- Maximum 120 words per language before links.
- No hashtags.
- Formatter appends cross-platform links.

Recommended structure:
ForgeView Lesson
Takeaway: [story hook]
Context: [story topic]
Lesson: [story lesson]

Return only final Telegram post text.
`;

return [{
  json: {
    ...$json,
    TELEGRAM_PROMPT: prompt,
  }
}];

let text = ($json.choices?.[0]?.message?.content || '').trim();

const followBlock = `Follow ForgeView:

X:
https://x.com/ForgeViewX

YouTube:
https://youtube.com/@ForgeViewGrowth`;

if (!text.includes('https://x.com/ForgeViewX') || !text.includes('https://youtube.com/@ForgeViewGrowth')) {
  text = text.replace(/Follow ForgeView:[\s\S]*$/i, '').trim();
  text = `${text}\n\n${followBlock}`;
}

return [{
  json: {
    telegram_public_channel: $('Set ForgeView Config').item.json.TELEGRAM_PUBLIC_CHANNEL,
    telegram_post: text
  }
}];

const story = $json.STORY_ENGINE || {
  category: $json.STORY_CATEGORY,
  topic: $json.STORY_TOPIC,
  hook: $json.STORY_HOOK,
  lesson: $json.STORY_LESSON,
};

const prompt = `
X POST GENERATOR

You are writing for ${$json.X_ACCOUNT}.

Use this Story Engine output as the only content source:
${JSON.stringify(story, null, 2)}

Rules:
- English only.
- One useful insight.
- Lead with the hook or lesson.
- Ground it in the ForgeView journey.
- Do not invent facts.
- Do not use generic internet advice.
- Do not repeat cooldown/exit/RSI unless the selected category is Trading Bot Lessons.
- Maximum 180 characters before the follow block.
- No hashtags, no emojis, no hype.
- Formatter appends links.

Return only the X post text.
`;

return [{
  json: {
    ...$json,
    X_PROMPT: prompt,
  }
}];

let post = ($json.choices?.[0]?.message?.content || '').trim();
post = post.replace(/^[`'"“”]+|[`'"“”]+$/g, '').trim();

const followBlock = `Follow ForgeView:
Telegram: https://t.me/ForgeViewCom
YouTube: https://youtube.com/@ForgeViewGrowth`;

post = post.replace(/Follow ForgeView:[\s\S]*$/i, '').trim();

if (post.length > 180) {
  post = post.slice(0, 177).trimEnd() + '...';
}

const finalPost = `${post}\n\n${followBlock}`;
const config = $('Set ForgeView Config').item.json;

const message = `X DRAFT - POST MANUALLY\n\n${finalPost}\n\nAccount: ${config.X_ACCOUNT}`;

return [{
  json: {
    x_post: finalPost,
    x_draft_message: message,
    x_drafts_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID
  }
}];

let raw = ($json.choices?.[0]?.message?.content || '').trim();
const config = $('Set ForgeView Config').item.json;

const requiredDescriptionBlock = `#Shorts\n\nTelegram:\nhttps://t.me/ForgeViewCom\n\nX:\nhttps://x.com/ForgeViewX`;

function stripJsonFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function buildNarrationScript(parsed) {
  if (parsed.narration_script) return String(parsed.narration_script).trim();
  const scenes = [];
  for (let i = 1; i <= 7; i++) {
    if (parsed[`scene${i}`]) scenes.push(String(parsed[`scene${i}`]).trim());
  }
  return scenes.map((scene, index) => `Scene ${index + 1}: ${scene}`).join('\n');
}

let parsed;
try {
  parsed = JSON.parse(stripJsonFence(raw));
} catch (e) {
  throw new Error(`Shorts draft OpenAI output was not valid JSON: ${e.message}`);
}

parsed.title = String(parsed.title || 'ForgeView Automation Lesson #Shorts').trim();
parsed.description = String(parsed.description || '').replace(/Follow ForgeView:[\s\S]*$/i, '').trim();
for (const line of requiredDescriptionBlock.split('\n')) {
  if (line && !parsed.description.includes(line)) parsed.description += `\n${line}`;
}
parsed.description = parsed.description.replace(/\n{3,}/g, '\n\n').trim();
parsed.narration_script = buildNarrationScript(parsed);
if (!Array.isArray(parsed.tags)) {
  parsed.tags = ['AI automation', 'trading bots', 'n8n', 'build in public', 'ForgeViewAI'];
}

raw = JSON.stringify(parsed, null, 2);

const message = `YOUTUBE SHORTS DRAFT - REVIEW MANUALLY\n\n${raw}\n\nProject: ${config.BRAND_NAME}`;

return [{
  json: {
    shorts_raw: raw,
    shorts_json: parsed,
    shorts_message: message,
    x_drafts_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID
  }
}];

const config = $('Set ForgeView Config').item.json;
const draft = $('Format Shorts Draft').item.json;

function stripJsonFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

let shortsJson = draft.shorts_json;
if (!shortsJson) {
  try {
    shortsJson = JSON.parse(stripJsonFence(draft.shorts_raw));
  } catch (error) {
    throw new Error(`Shorts draft is not valid JSON: ${error.message}`);
  }
}

let title = String(shortsJson.title || 'ForgeView Automation Lesson #Shorts').replace(/\s+/g, ' ').trim();
if (!/#Shorts/i.test(title)) title = `${title} #Shorts`;
if (title.length > 100) title = title.slice(0, 97).trimEnd() + '...';

let description = String(shortsJson.description || '').trim();
if (!description) {
  description = 'A ForgeView build-in-public lesson from AI automation, trading bots, and workflow reliability.';
}
const requiredDescriptionBlock = `#Shorts\n\nTelegram:\nhttps://t.me/ForgeViewCom\n\nX:\nhttps://x.com/ForgeViewX`;
for (const line of requiredDescriptionBlock.split('\n')) {
  if (line && !description.includes(line)) description += `\n${line}`;
}
description = description.replace(/\n{3,}/g, '\n\n').trim();

const tags = Array.isArray(shortsJson.tags)
  ? shortsJson.tags.map(String).filter(Boolean)
  : ['AI automation', 'trading bots', 'n8n', 'build in public', 'ForgeViewAI'];
const narrationScript = String(shortsJson.narration_script || '').trim();

return [{
  json: {
    draft_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID,
    youtube_channel_handle: '@ForgeViewGrowth',
    privacyStatus: 'private',
    categoryId: '28',
    title,
    description,
    tags,
    tags_text: tags.join(', '),
    narration_script: narrationScript,
    shorts_json: shortsJson,
    local_project_root: 'D:\\ForgeViewAI',
    shorts_generator_dir: 'D:\\ForgeViewAI\\content\\video\\shorts-generator',
    output_path: 'D:\\ForgeViewAI\\output\\media\\videos\\short.mp4'
  }
}];

const prepared = $('Prepare Shorts Generator Payload').item.json;
const bridge = $json || {};
let videoUrl = bridge.video_url || bridge.download_url || bridge.mp4_url;

if (!videoUrl) {
  throw new Error('Local Shorts Generator bridge did not return video_url/download_url/mp4_url for the generated MP4.');
}

if (/^http:\/\/(localhost|127\.0\.0\.1):/i.test(videoUrl)) {
  const bridgeUrl = 'https://FORGEVIEW_BRIDGE_URL/forgeview/render-short';
  if (bridgeUrl.includes('FORGEVIEW_BRIDGE_URL')) {
    throw new Error('BRIDGE URL NOT CONFIGURED');
  }
  videoUrl = bridgeUrl.replace(/\/forgeview\/render-short\/?$/, '/files/short.mp4');
}

return [{
  json: {
    ...prepared,
    bridge_status: bridge.status || (bridge.ok ? 'ok' : 'unknown'),
    bridge_message: bridge.message || '',
    bridge_video_path: bridge.video_path || '',
    generated_video_url: videoUrl
  }
}];

const upload = $json;
const prepared = $('Prepare Shorts Generator Payload').item.json;
const videoId = upload.id || upload.videoId || upload.snippet?.resourceId?.videoId || '';
const url = videoId ? `https://www.youtube.com/watch?v=${videoId}` : 'URL unavailable';

return [{
  json: {
    draft_chat_id: prepared.draft_chat_id,
    video_id: videoId,
    video_url: url,
    privacyStatus: 'private',
    title: prepared.title,
    confirmation_text: `UPLOAD SUCCESS\n\nVideo ID:\n${videoId || 'unknown'}\n\nURL:\n${url}\n\nPrivacy:\nprivate`
  }
}];

const categories = [
  'Build In Public',
  'Engineering Lessons',
  'Founder Lessons',
  'Trading Bot Lessons',
  'AI Automation Lessons',
  'Systems & Growth',
];

const forgeViewTopics = {
  'Build In Public': [
    {
      topic: 'Local YouTube uploads failed, so publishing moved into n8n Cloud',
      hook: 'The upload tool was not the real system.',
      lesson: 'When local execution keeps failing, move the operation into the orchestration layer instead of fighting the same failure forever.',
    },
    {
      topic: 'Cloudflare quick tunnels returned 530 while the local bridge worked',
      hook: 'The local system worked, but the public route failed.',
      lesson: 'Automation is only as reliable as the path between systems, not just the script that runs locally.',
    },
    {
      topic: 'The MP4 branch looked connected but n8n needed nested connection arrays',
      hook: 'A workflow can look finished and still be disconnected.',
      lesson: 'In automation, structure is behavior. A small JSON shape error can break the whole pipeline.',
    },
    {
      topic: 'Telegram draft delivery became the review layer before public posting',
      hook: 'The draft channel became the control room.',
      lesson: 'For early-stage automation, manual review is not failure. It is the safety layer before scale.',
    },
  ],
  'Engineering Lessons': [
    {
      topic: 'Fixing one branch exposed another hidden workflow dependency',
      hook: 'The bug was not in the obvious node.',
      lesson: 'The last step often fails because upstream assumptions were never tested end to end.',
    },
    {
      topic: 'Binary MP4 download had to match Telegram binary property names',
      hook: 'The file existed, but Telegram could not see it.',
      lesson: 'Automation breaks when data formats do not match exactly, even if every node looks reasonable.',
    },
    {
      topic: 'The bridge needed fail-fast behavior instead of silently using a placeholder URL',
      hook: 'A placeholder should fail loudly.',
      lesson: 'A clear error is safer than a workflow that quietly continues with broken infrastructure.',
    },
    {
      topic: 'Audio looked rendered but the final MP4 track ended early',
      hook: 'The video was complete, but the sound was not.',
      lesson: 'Media pipelines need duration validation, not just successful render status.',
    },
  ],
  'Founder Lessons': [
    {
      topic: 'Midjourney was delayed because the local generator had to work first',
      hook: 'Better tools were not the bottleneck.',
      lesson: 'Before buying another tool, prove the workflow can ship with the tools already available.',
    },
    {
      topic: 'Manual YouTube upload was chosen before full auto-publishing',
      hook: 'Manual was the faster safe step.',
      lesson: 'The right MVP is not maximum automation. It is the smallest reliable path to publishing.',
    },
    {
      topic: 'ForgeView prioritized output over perfect infrastructure',
      hook: 'The system only matters if it produces work.',
      lesson: 'Speed beats perfection when each shipped artifact teaches the next constraint.',
    },
    {
      topic: 'The first product direction stayed no-SaaS and AI-generated',
      hook: 'A service can sell before software exists.',
      lesson: 'The fastest first sale usually comes from a useful deliverable, not a platform.',
    },
  ],
  'Trading Bot Lessons': [
    {
      topic: 'Spot Bot rarely opened trades because filters were too strict',
      hook: 'A safe bot can become an inactive bot.',
      lesson: 'Risk filters need balance: protecting capital is good, but over-filtering can remove opportunity entirely.',
    },
    {
      topic: 'Loss cooldown had to block entries but never exits',
      hook: 'A cooldown should never trap recovery.',
      lesson: 'Risk controls should stop weak new trades, not block actions that reduce risk.',
    },
    {
      topic: 'RSI anti-late-short filters were added after exit safety was fixed',
      hook: 'Entry quality matters after exits are protected.',
      lesson: 'Trading logic should first protect the downside, then improve selectivity.',
    },
    {
      topic: 'Phantom positions came from committing state before confirmed orders',
      hook: 'State cannot be trusted before execution is confirmed.',
      lesson: 'Trading systems must treat exchange confirmation as the source of truth.',
    },
  ],
  'AI Automation Lessons': [
    {
      topic: 'AI-generated images created fake UI text until prompts banned readable symbols',
      hook: 'AI visuals failed in the details.',
      lesson: 'AI generation needs constraints that match the medium, especially when fake text can ruin trust.',
    },
    {
      topic: 'The Shorts generator improved when visuals became metaphors instead of fake screenshots',
      hook: 'Screens looked technical but made the video worse.',
      lesson: 'AI video assets work better when they communicate the idea visually instead of imitating interfaces.',
    },
    {
      topic: 'Voice, subtitles, images, and music had to be validated separately',
      hook: 'One successful render did not prove the video worked.',
      lesson: 'AI automation needs checkpoints for each modality, not one final success flag.',
    },
    {
      topic: 'The Story Engine was added because latest-context prompts became repetitive',
      hook: 'The prompt was technically correct but creatively stuck.',
      lesson: 'AI systems need memory and rotation, or they keep optimizing around the last visible event.',
    },
  ],
  'Systems & Growth': [
    {
      topic: 'ForgeView moved from scripts to one unified content workflow',
      hook: 'A pile of scripts is not an operating system.',
      lesson: 'Growth automation becomes scalable when generation, review, rendering, and delivery live in one pipeline.',
    },
    {
      topic: 'Draft channels became the bottleneck control point for growth content',
      hook: 'The review step became part of the system.',
      lesson: 'Good systems do not remove human judgment too early. They place it where it has the most leverage.',
    },
    {
      topic: 'The bridge connected local rendering with cloud orchestration',
      hook: 'Cloud automation still needed a local machine.',
      lesson: 'Hybrid systems are normal in early operations: cloud coordinates, local tools execute.',
    },
    {
      topic: 'ForgeView content needed a journey engine, not a topic generator',
      hook: 'Random topics do not build a project narrative.',
      lesson: 'A growth system should turn real work into lessons, not invent content disconnected from execution.',
    },
  ],
};

function normalizeTopic(topic) {
  return String(topic || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (error) {
  staticData = {};
}

const previousCount = Number(staticData.story_post_count || 0);
const categoryIndex = previousCount % categories.length;
const category = categories[categoryIndex];
const recentTopics = Array.isArray(staticData.recent_story_topics) ? staticData.recent_story_topics : [];
const recentNormalized = recentTopics.map(normalizeTopic);

const candidates = forgeViewTopics[category] || [];
let selected = candidates.find(item => !recentNormalized.includes(normalizeTopic(item.topic)));
if (!selected) {
  selected = candidates[previousCount % Math.max(1, candidates.length)] || {
    topic: 'ForgeView workflow reliability work',
    hook: 'The system improved through real failures.',
    lesson: 'Ground content in the work that actually happened.',
  };
}

const story = {
  category,
  topic: selected.topic,
  hook: selected.hook,
  lesson: selected.lesson,
};

try {
  staticData.story_post_count = previousCount + 1;
  staticData.recent_story_topics = [selected.topic, ...recentTopics.filter(topic => normalizeTopic(topic) !== normalizeTopic(selected.topic))].slice(0, 12);
  staticData.last_story_engine_output = story;
} catch (error) {
  // Static data is best-effort. The story still emits deterministically.
}

return [{
  json: {
    ...$json,
    STORY_ENGINE: story,
    STORY_CATEGORY: story.category,
    STORY_TOPIC: story.topic,
    STORY_HOOK: story.hook,
    STORY_LESSON: story.lesson,
    STORY_ENGINE_JSON: JSON.stringify(story, null, 2),
    STORY_ROTATION_INDEX: categoryIndex,
    STORY_POST_COUNT: previousCount + 1,
    RECENT_STORY_TOPICS: [selected.topic, ...recentTopics].slice(0, 12),
  }
}];
